from django.middleware.gzip import GZipMiddleware

class SSEAwareGZipMiddleware(GZipMiddleware):
    #SSE no puede bufferizarse: compress_sequence (Django 5.2.x) no hace
    #flush por chunk y el stream entero saldría en un solo burst al cierre.
    def process_response(self, request, response):
        if (response.get('Content-Type') or '').startswith('text/event-stream'):
            return response
        return super().process_response(request, response)

# DaventProject/settings.py MIDDLEWARE:
#   'DaventProject.middleware.SSEAwareGZipMiddleware',  # en lugar de
#   'django.middleware.gzip.GZipMiddleware',
